INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 5, 'Security and Breach Response', 'Security Measures', 1, 'Has the organisation implemented appropriate technical security measures to protect personal information?', 'Section 19 requires organisations to implement appropriate and reasonable technical security measures.', 'POPIA Section 19 security safeguards; ISO 27701 cl.6.9–6.13 technical security', 'Critical', 'Technical security documentation; security controls inventory; penetration testing records; vulnerability management; security architecture.', 'Implement comprehensive technical security measures. Conduct regular security assessments and penetration testing. Maintain vulnerability management programme.', 'P5_SEC_1'),
('popia', 5, 'Security and Breach Response', 'Security Measures', 2, 'Has the organisation implemented appropriate organisational security measures?', 'Section 19 requires organisations to implement appropriate and reasonable organisational security measures.', 'POPIA Section 19 security safeguards; ISO 27701 cl.6.9–6.13 organisational security', 'Critical', 'Security policies and procedures; security roles and responsibilities; security training; security awareness programme; incident response team.', 'Implement comprehensive organisational security measures. Establish security roles and responsibilities. Conduct regular security training.', 'P5_SEC_2'),
('popia', 5, 'Security and Breach Response', 'Security Measures', 3, 'Are security measures appropriate to the risk level of the personal information being processed?', 'Security measures must be appropriate to the risk level and nature of personal information being processed.', 'POPIA Section 19 security safeguards; ISO 27701 cl.6.9–6.13 risk-based security; ISO 27701 cl.6.1.3 risk assessment', 'High', 'Risk assessment methodology; security control selection process; evidence of risk-based decisions; security testing records; threat modelling.', 'Implement risk-based approach to security. Conduct regular risk assessments. Select security controls based on risk level and threat modelling.', 'P5_SEC_3'),
('popia', 5, 'Security and Breach Response', 'Security Measures', 4, 'Are encryption standards implemented for sensitive personal information?', 'Section 19 requires appropriate security measures, which typically includes encryption for sensitive data.', 'POPIA Section 19 security safeguards; ISO 27701 cl.6.9–6.13 encryption; POPIA Regulations technical standards', 'Critical', 'Encryption policy and standards; encryption implementation records; key management procedures; encryption testing; compliance verification.', 'Implement encryption for sensitive personal information. Establish key management procedures. Regularly test encryption effectiveness.', 'P5_SEC_4'),
('popia', 5, 'Security and Breach Response', 'Security Measures', 5, 'Are access controls implemented to limit access to personal information on a need-to-know basis?', 'Section 19 security safeguards requires appropriate access controls to prevent unauthorised access.', 'POPIA Section 19 security safeguards; ISO 27701 cl.6.9–6.13 access control; POPIA Regulations access control', 'Critical', 'Access control policy; user access rights management; access review processes; privileged access monitoring; access request procedures.', 'Implement need-to-know access controls. Regularly review and update access rights. Monitor privileged access usage.', 'P5_SEC_5'),
('popia', 5, 'Security and Breach Response', 'Breach Detection', 6, 'Does the organisation have procedures for detecting security compromises involving personal information?', 'Section 22 requires organisations to identify security compromises and take appropriate action.', 'POPIA Section 22 security compromises; ISO 27701 cl.6.13.2 incident management', 'Critical', 'Breach detection procedures; monitoring systems; alert mechanisms; incident response team; breach notification procedures.', 'Implement breach detection procedures and monitoring systems. Establish incident response team and notification procedures.', 'P5_BR_1'),
('popia', 5, 'Security and Breach Response', 'Breach Detection', 7, 'Are staff trained to recognise and report potential security compromises?', 'Staff awareness is critical for timely breach detection and response.', 'POPIA Section 22 security compromises; ISO 27701 cl.6.13.2 incident management; security awareness training', 'High', 'Security awareness training programme; phishing simulations; incident reporting procedures; staff recognition programmes.', 'Implement comprehensive security awareness training. Conduct phishing simulations. Establish clear incident reporting procedures for staff.', 'P5_BR_2'),
('popia', 5, 'Security and Breach Response', 'Breach Notification', 8, 'Does the organisation have procedures for notifying security compromises "as soon as reasonably possible"?', 'Section 22 requires notification "as soon as reasonably possible" after discovery - there is no materiality threshold.', 'POPIA Section 22 security compromises; ISO 27701 cl.6.13.2 incident management; Information Regulator breach notification', 'Critical', 'Breach notification procedures; notification templates; Information Regulator contact details; notification record-keeping.', 'Implement breach notification procedures. Establish notification templates and contact lists. Record all breach notifications.', 'P5_BR_3'),
('popia', 5, 'Security and Breach Response', 'Breach Notification', 9, 'Does the organisation notify both the Information Regulator and affected data subjects?', 'Section 22 requires notification to both the Information Regulator and affected data subjects.', 'POPIA Section 22 security compromises; ISO 27701 cl.6.13.2 incident management; Information Regulator breach notification', 'Critical', 'Breach notification procedures for Information Regulator; data subject notification procedures; notification templates; notification logs.', 'Implement dual notification procedures for Information Regulator and data subjects. Use Information Regulator eServices portal for regulator notification.', 'P5_BR_4'),
('popia', 5, 'Security and Breach Response', 'Breach Response', 10, 'Does the organisation have a documented incident response plan for security compromises?', 'Section 22 requires organisations to take appropriate action in response to security compromises.', 'POPIA Section 22 security compromises; ISO 27701 cl.6.13.2 incident management; NIST incident response framework', 'High', 'Incident response plan; incident response team; communication procedures; post-incident analysis; lessons learned documentation.', 'Develop comprehensive incident response plan. Establish incident response team. Conduct post-incident analysis and document lessons learned.', 'P5_BR_5');